%[text] # Mathieu Equation: Effect of Damping on Stability
%[text] [Open in MATLAB Online](https://matlab.mathworks.com/open/github/v1?repo=mxmGrss/phasorArray_Toolbox&file=Exemples/MathieuEquation_Comparative.m)
%[text] 
%[text] **Abstract**: Comparative analysis of the Mathieu equation across four
%[text] configurations (stable/unstable × undamped/damped) using the PhasorArray Toolbox.
%[text] We use `PhasorSS.initial()` for time-domain simulation and `HmqNEig` to
%[text] inspect the Floquet exponents in the harmonic domain.
%[text] 
%[text] ## 1. Theoretical Background
%[text] The **damped** Mathieu equation reads:
%[text] $\\ddot{x} + \\delta,\\dot{x} + \[a - 2q\\cos(2t)\],x = 0$ 
%[text] with LTP state-space representation $\\dot{x} = A(t)x$:
%[text] 
%[text] $&dollar&;A(t) = \\underbrace{\\pmatrix{0 & 1\\cr -a & -\\delta}}\_{A\_0}    + \\underbrace{\\pmatrix{0 & 0\\cr q & 0}}\_{A\_c}\\cos(2t)  + \\text{c.c.}&dollar&;$
%[text] Four test points are chosen from the Strutt-Ince diagram:
%[text] two inside a stability tongue (unstable) and two outside (stable),
%[text] with and without damping $\\delta$.
%%
%[text] ## 2. Setup
T     = pi;           % Period of cos(2t) is pi
omega = 2*pi/T;       % Fundamental frequency (omega = 2 rad/s)
h_hss = 15;           % Harmonic truncation order for HmqNEig

t_sim = linspace(0, 20*T, 20000);  % Simulation horizon

% Two q values: q1 (stable everywhere), q2 (unstable/marginal/stable)
a = 0.8;
q1 = 0.01;
q2 = 0.3144;
deltas = [0, 0.25, 0.4];

cases = [a, q1, deltas(1);
    a, q1, deltas(2);
    a, q1, deltas(3);
    a, q2, deltas(1);
    a, q2, deltas(2);
    a, q2, deltas(3)];

labels = { '$q1=0.01$, $\delta=0$'   , ...
    '$q1=0.01$, $\delta=0.1$' , ...
    '$q1=0.01$, $\delta=0.2$' , ...
    '$q2=0.20$, $\delta=0$'   , ...
    '$q2=0.20$, $\delta=0.1$' , ...
    '$q2=0.20$, $\delta=0.2$' };
%%
%[text] ## 3. Time-Domain Simulation with PhasorSS
%[text] For each case we build a `PhasorArray` carrying the constant and
%[text] first-harmonic Fourier coefficients of $A(t)$, wrap it in a `PhasorSS`,
%[text] then call `initial()` to integrate from $x\_0=\[1;0\]$.
figure(1)
clf %[output:01771666]
Tgcf=tiledlayout(2,2); %[output:01771666]
y=cell(6,2);
t=cell(6,2);
for i = [1 2 4 5]
    a = cases(i,1);  q = cases(i,2);  d = cases(i,3);

    % A0 = constant part, Ac = cosine coefficient (PhasorArray convention:
    %   A(t) = A0 + Ac*e^{j*omega*t} + conj(Ac)*e^{-j*omega*t}
    %        = A0 + 2*real(Ac)*cos(omega*t) - 2*imag(Ac)*sin(omega*t)
    % So for 2q*cos(2t) coefficient we pass Ac = [0 0; q 0] )
    Ar  = PhasorArray([0 1 ; -a -d], [0 0 ; q 0], 'isreal', true);
    sys = PhasorSS(Ar, [0;0], [1 0], 0, T);

    [yy, tt] = initial(sys, [1; 0], t_sim);
    y{i,1} = yy;
    t{i,1} = tt;

    nexttile() %[output:01771666]
    plot(t{i,1}, squeeze(y{i,1}), 'LineWidth', 1.5)
    hold on; grid on

    [yy, tt] = initial(sys, [0; 1], t_sim);
    y{i,2} = yy;
    t{i,2} = tt;
    plot(t{i,2}, squeeze(y{i,2}), 'LineWidth', 1.5)
    title(sprintf('$a=%.1f, q=%.2f, \\delta=%.2f$', a, q, d), Interpreter='latex')
    xlabel('Time (s)'); ylabel('x (rad)')

end

% title(Tgcf,'Mathieu Equation - Initial Condition Response')
subtitle(Tgcf,'$\ddot{x} + \delta \dot{x} +(a -2q\cos(2t))x = 0$') %[output:01771666]
applyStyle(gcf,'FigurePreset', 'beamer169_full') %[output:01771666]

saveStyledFigure(gcf, 'Mathieu_TimeResponse', 'Formats', {'pdf', 'png','eps'})
%%
%[text] ## 4. HSS Spectrum: Floquet Exponents via HmqNEig
%[text] `HmqNEig(N, T)` returns the $N$ eigenvalues of the harmonic operator
%[text] closest to the imaginary axis -- the principal **Floquet exponents**.
%[text] Stability criterion: $\\max,\\mathrm{Re}(\\lambda\_i) \\leq 0$.
figure(2)
clf
T2 = tiledlayout(2,3);
for i = 1:6
    i
    a = cases(i,1);  q = cases(i,2);  d = cases(i,3);

    Ar = PhasorArray([0 1 ; -a -d], [0 0 ; q 0], 'isreal', true);
    ev = Ar.HmqNEig(70, T);

    sT2 = tiledlayout(T2,1,2);
    sT2.Layout.Tile=i;
    sT2.TileSpacing='tight';
    sT2.Padding='tight';
    nexttile(sT2,1)
    plot(t{i,1}, squeeze(y{i,1}), 'LineWidth', 1.5)
    hold on
    plot(t{i,2}, squeeze(y{i,2}), 'LineWidth', 1.5)
        xlabel('Time (s)'); ylabel('x (rad)')

    nexttile(sT2,2)
    plot(real(ev), imag(ev), 'x', 'MarkerSize', 6, 'LineWidth', 1.2)
    hold on; grid on
    xline(0, '--k', 'LineWidth', 0.8)        % stability boundary
    xlim([-0.6 0.6])
    ylim([-2 2]*omega)
    title(sT2,sprintf('$a=%.1f$, $q=%.2f$, $\\delta=%.2f$',  a, q, d),Interpreter="latex")
    xlabel('$Re(\mu)$',Interpreter="latex"'); ylabel('$Im(\mu)$',Interpreter="latex"')

   [true_mu,true_l]=findTruelm(ev,T,2)
   subtitle(sT2,sprintf(['$\\lambda_1 = %.3f  e^{ j%.3f j}$ et $\\mu_1 = %.3f + { %.3f j}$,\n $\\lambda_2 = %.3f  e^{ %.3f j}$ et $\\mu_2 = %.3f  + { %.3f j}$.'], ...
       abs(true_l(1)),angle(true_l(1)),real(true_mu(1)),imag(true_mu(1)),abs(true_l(2)),angle(true_l(2)),real(true_mu(2)),imag(true_mu(2))),Interpreter="latex"')
end

title(T2,sprintf('HSS Spectrum - Floquet Exponents (HmqNEig) - $a = %.2f$',a))
subtitle(T2,'Exp de floquet et Multiplicateurs')
% applyStyle(gcf, 'TextInterpreter',"latex",'FigurePreset', 'beamer169_full', ...
    % 'ReducedFontSize',2,'FontSize',10)
% saveStyledFigure(gcf, 'Mathieu_FloquetSpectrum', 'Formats', {'pdf', 'png','eps'})


%[text] ## 5. Conclusion
%%
%[text] ## 5. Strutt-Ince Diagram: Stability Boundaries for Damping
%[text] We plot the critical boundary $q\_\\text{crit} \\approx \\delta$ for $a=1$ and superpose the 6 cases.
% ---- Strutt diagram disabled (expensive parfor scan ~10 min) ----
%{
figure(3)
clf
Na = 71; Nq = 81; % Reduced grid for demo
a_range = linspace(-1, 6, Na);
q_range = linspace(-2, 2, Nq);
[A, Q] = meshgrid(a_range, q_range);
Stable = zeros(size(A) );
SStable = zeros(size(A,1),size(A,2),numel(deltas));
for di = 1:numel(deltas)
    dd = deltas(di)
    parfor idx = 1:numel(A)
        Ar_scan = PhasorArray([0 1 ; -A(idx) -dd], [0 0 ; Q(idx) 0], 'isreal', true);
        Stable(idx) = max(real(Ar_scan.HmqNEig(20, T))) ;
    end
    SStable(:,:,di) = Stable;
    nexttile(di)
    surf(a_range, q_range, Stable);
    shading interp
    % set(gca, 'YDir', 'normal');
    % colormap([0.8 0.3 0.3; 0.3 0.8 0.3]);
    xlabel('a'); ylabel('q'); title('Stability Tongues');
    colormap( "jet")
end

linkaxes(findall(gcf,'type','Axes'),'z')

clim(findall(gcf,'type','Axes'),[-1 1]*max(SStable,[],'all'))

%%

figure(3)
clf
tiledlayout(1,3)
for di = 1:numel(deltas)
    dd = deltas(di)
    nexttile(di)
    surf(a_range, q_range, SStable(:,:,di)-1e-3);
    shading interp
    title(sprintf('Stability Tongues $\\delta=%.2f$',dd), Interpreter='latex');
    xlabel('a'); ylabel('q');
    colormap( "jet")
    hold on; % Pour ne pas effacer ton graph actuel
    xl = xlim;
    yl = ylim;
    [X, Y] = meshgrid(xl, yl);
    Z = zeros(size(X));

    % Affichage du plan transparent
    % h = surf(X, Y, Z, 'FaceAlpha', 0.2, 'EdgeColor', 'none', 'FaceColor', 'k');
    % scatter3(a,q1,dd,'k*','LineWidth',2)
    % scatter3(a,q2,dd,'k*','LineWidth',2)
    % FaceAlpha : 0 (invisible) à 1 (opaque). 0.2 est bien pour la transparence.

    [C, h] = contour3(a_range, q_range, SStable(:,:,di)-1e-3, [0 0], 'k', 'LineWidth', 4);
end
linkaxes(findall(gcf,'type','Axes'),'z')

clim(findall(gcf,'type','Axes'),[-1 1]*max(SStable,[],'all'))
colorbar('eastoutside')

h = linkprop(findall(gcf,'type','Axes'), {'View', 'XLim', 'YLim', 'ZLim'});
view([25 -40 45])
applyStyle(gcf,'FigurePreset', 'beamer169_full')
saveStyledFigure(gcf, 'Mathieu_StabilityTongues', 'Formats', {'pdf', 'png','eps'})
%}
% ---- End disabled Strutt section ----
%[text] - **Undamped** cases: stabilité gouvernée par la Strutt-Ince (q=0.05 stable, q=0.20 instable).
%[text] - **Damped** cases: la langue d'instabilité se déplace ($q\_\\text{crit} \\approx \\delta$).
%[text] - Les points étudiés illustrent la transition instable → marginal → stable.
%[text] - `HmqNEig` confirme la frontière spectrale sans simulation. \
%%
%[text] ## 6. LQR Stabilization of an Unstable Zone (Harmonic Riccati)
%[text] We pick the unstable point $(a=0.8,, q=0.3144,, \\delta=0)$ and design a
%[text] periodic state-feedback $u = -K(\\theta)x$ via `RicHarmonicKlein`.
%[text] Weights: $Q = \\mathrm{diag}(10,1)$, $R = 1$ (penalise position more than velocity).

a_stab  = 0.8;
q_stab  = 0.3144;
d_stab  = 0.0;
h_ric   = 15;
t_stab  = linspace(0, 3*T, 4000);

% Open-loop model (unstable Mathieu point)
Ar_ol = PhasorArray([0 1; -a_stab -d_stab], [0 0; q_stab 0], 'isreal', true);
B_stab = PhasorArray([0; 1]);

% Verify open-loop instability
mu_ol = HmqNEig(Ar_ol, h_ric, T);
if max(real(mu_ol)) > 0, ol_str = 'UNSTABLE'; else, ol_str = 'stable'; end
fprintf('Open-loop:  max Re(mu) = %.4f  (%s)\n', max(real(mu_ol)), ol_str);

% LQR weights: penalise position (x1) more than velocity (x2)
Q_w = PhasorArray(diag([10, 1]));
R_w = PhasorArray(1);
K0  = PhasorArray(ones(1, 2));

% Harmonic Riccati (iterative fixed-point)
[K_ric, r, info_ric] = RicHarmonicKlein(Ar_ol, B_stab, Q_w, R_w, K0, T, ...
    'maxIter', 150, 'thresholdResidual', 1e-6, 'autoUpdateh', true);
fprintf('Riccati converged at h = %d\n', info_ric.h);

% Closed-loop system
Ar_cl = Ar_ol - B_stab * K_ric;
mu_cl = HmqNEig(Ar_cl, h_ric, T);
if max(real(mu_cl)) < 0, cl_str = 'STABLE'; else, cl_str = 'UNSTABLE'; end
fprintf('Closed-loop: max Re(mu) = %.4f  (%s)\n', max(real(mu_cl)), cl_str);

% Simulate open-loop and closed-loop from same initial condition
sys_ol = PhasorSS(Ar_ol, zeros(2,1), eye(2), 0, T);
sys_cl = PhasorSS(Ar_cl, zeros(2,1), eye(2), 0, T);
x0 = [1; 0];
[y_ol, t_ol] = initial(sys_ol, x0, t_stab);
[y_cl, t_cl] = initial(sys_cl, x0, t_stab);

% Plot
figure(4); clf
tl = tiledlayout(1, 3);

nexttile(1)
plot(t_ol, squeeze(y_ol(:,1)),'r', 'LineWidth', 1.5)
hold on; grid on
plot(t_cl, squeeze(y_cl(:,1)), 'b', 'LineWidth', 1.5)
xlabel('Time (s)'); ylabel('x_1 (position)')
legend('Open-loop (unstable)', 'Closed-loop (LQR)', 'Location', 'northwest')
title('State $x_1$', 'Interpreter', 'latex')

nexttile(2)
plot(t_ol, squeeze(y_ol(:,2)), 'r', 'LineWidth', 1.5)
hold on; grid on
plot(t_cl, squeeze(y_cl(:,1)), 'b', 'LineWidth', 1.5)
xlabel('Time (s)'); ylabel('x_2 (velocity)')
title('State $x_2$', 'Interpreter', 'latex')

nexttile(3)
plot(real(mu_ol), imag(mu_ol), 'rx', 'MarkerSize', 8, 'LineWidth', 1.5)
hold on; grid on
plot(real(mu_cl), imag(mu_cl), 'b+', 'MarkerSize', 8, 'LineWidth', 1.5)
xline(0, '--k', 'LineWidth', 0.8)
xlim([-1.5 1.5]); ylim([-1 1]*6*omega)
xlabel('$\mathrm{Re}(\mu)$', 'Interpreter', 'latex')
ylabel('$\mathrm{Im}(\mu)$', 'Interpreter', 'latex')
legend('Open-loop', 'Closed-loop', 'Location', 'northeast')
title('Floquet exponents', 'Interpreter', 'latex')

title(tl, sprintf('Mathieu LQR -- $a=%.1f$, $q=%.4f$, $Q=\\mathrm{diag}(10,1)$, $R=1$', ...
    a_stab, q_stab), 'Interpreter', 'latex')

% applyStyle(gcf, 'FigurePreset', 'beamer169_full', 'FontSize', 10)
% saveStyledFigure(gcf, 'Mathieu_LQR_Stabilization', 'Formats', {'pdf', 'png', 'eps'})
%%
function [true_mu, true_l] = findTruelm(ev,T,nx)
% 1. Récupération de tes données (les exposants tronqués)
% ev = Ar.HmqNEig(70, T);
% nx = 2; % size(A,1) : Le nombre de vrais multiplicateurs qu'on cherche

% 2. Repliement dans le plan complexe (Exposants -> Multiplicateurs)
m = exp(T * ev);
N = length(m);

% 3. Paramétrage du KDE
% "bw" (bandwidth) est la largeur de la gaussienne.
% Comme la méthode HSS est très précise au centre, les bons points
% sont quasi-identiques. 1e-4 est une excellente valeur.
bw = 1e-4;

% 4. Évaluation de la densité KDE sur chaque point
density = zeros(N, 1);
for i = 1:N
    % Distance au carré entre le point i et TOUS les autres points
    dist_sq = abs(m(i) - m).^2;

    % Somme des noyaux gaussiens (Formule du KDE)
    density(i) = sum(exp(-dist_sq / (2 * bw^2)));
end

% 5. Extraction des pics (les 'nx' clusters)
true_l = zeros(nx, 1);
m_pool = m;
dens_pool = density;

for k = 1:nx
    if isempty(m_pool)
        % Cas rare : Résonance parfaite (valeur propre double).
        % Tout a été effacé au tour précédent, on duplique la racine.
        true_l(k) = true_l(k-1);
        continue;
    end

    % Trouver le point avec la plus forte densité
    [~, max_idx] = max(dens_pool);
    peak_m = m_pool(max_idx);
    true_l(k) = peak_m;

    % Effacer ce cluster du pool pour trouver le suivant
    % (On supprime tous les points dans un rayon de 5*bw)
    mask = abs(m_pool - peak_m) > 5 * bw;
    m_pool = m_pool(mask);
    dens_pool = dens_pool(mask);
end

% 6. Retour aux valeurs principales des exposants de Floquet
true_mu = log(true_l) / T;
end


